enhanced_schema:
{
  "tables": [
    {
      "table_name": "size_conversions",
      "table_description": "Table to store size conversion standards and body measurements for clothing items across different regions.",
      "columns": [
        {
          "name": "size_id",
          "type": "INTEGER",
          "description": "Unique identifier for each size conversion entry."
        },
        {
          "name": "website_size",
          "type": "VARCHAR",
          "description": "Standard size as listed on the company's website."
        },
        {
          "name": "eu_size",
          "type": "VARCHAR",
          "description": "European size standard."
        },
        {
          "name": "ita_size",
          "type": "VARCHAR",
          "description": "Italian size standard."
        },
        {
          "name": "usa_size",
          "type": "VARCHAR",
          "description": "USA size standard."
        },
        {
          "name": "uk_size",
          "type": "VARCHAR",
          "description": "UK size standard."
        },
        {
          "name": "japan_size",
          "type": "VARCHAR",
          "description": "Japan size standard."
        },
        {
          "name": "aus_size",
          "type": "VARCHAR",
          "description": "Australian size standard."
        },
        {
          "name": "breast_circumference_cm",
          "type": "INTEGER",
          "description": "Breast circumference measured in centimeters."
        },
        {
          "name": "breast_circumference_inch",
          "type": "INTEGER",
          "description": "Breast circumference measured in inches."
        },
        {
          "name": "pelvis_cm",
          "type": "INTEGER",
          "description": "Pelvis circumference measured in centimeters."
        },
        {
          "name": "pelvis_inch",
          "type": "INTEGER",
          "description": "Pelvis circumference measured in inches."
        },
        {
          "name": "waist_cm",
          "type": "INTEGER",
          "description": "Waist circumference measured in centimeters."
        },
        {
          "name": "waist_inch",
          "type": "INTEGER",
          "description": "Waist circumference measured in inches."
        },
        {
          "name": "bust_length_cm",
          "type": "INTEGER",
          "description": "Bust length measured in centimeters for total body swimwear."
        },
        {
          "name": "bust_length_inch",
          "type": "INTEGER",
          "description": "Bust length measured in inches for total body swimwear."
        },
        {
          "name": "arm_length_cm",
          "type": "INTEGER",
          "description": "Arm length measured in centimeters."
        },
        {
          "name": "arm_length_inch",
          "type": "INTEGER",
          "description": "Arm length measured in inches."
        },
        {
          "name": "leg_length_cm",
          "type": "INTEGER",
          "description": "Leg length measured in centimeters."
        },
        {
          "name": "leg_length_inch",
          "type": "INTEGER",
          "description": "Leg length measured in inches."
        },
        {
          "name": "shoulder_width_cm",
          "type": "INTEGER",
          "description": "Shoulder width measured in centimeters."
        },
        {
          "name": "shoulder_width_inch",
          "type": "INTEGER",
          "description": "Shoulder width measured in inches."
        },
        {
          "name": "category",
          "type": "VARCHAR",
          "description": "Clothing category, e.g., swimwear, dresses."
        },
        {
          "name": "created_at",
          "type": "DATETIME",
          "description": "Timestamp when the size entry was created."
        },
        {
          "name": "updated_at",
          "type": "DATETIME",
          "description": "Timestamp when the size entry was last updated."
        }
      ],
      "primary_key": [
        "size_id"
      ],
      "foreign_keys": []
    },
    {
      "table_name": "user_profiles",
      "table_description": "Table to store user profiles and their roles within the system.",
      "columns": [
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "Unique identifier for each user."
        },
        {
          "name": "username",
          "type": "VARCHAR",
          "description": "Username of the user."
        },
        {
          "name": "role",
          "type": "VARCHAR",
          "description": "Role of the user in the system, e.g., admin, customer_service, customer."
        },
        {
          "name": "preferred_sizes",
          "type": "VARCHAR",
          "description": "Comma-separated list of preferred sizes."
        },
        {
          "name": "created_at",
          "type": "DATETIME",
          "description": "Timestamp when the user profile was created."
        },
        {
          "name": "updated_at",
          "type": "DATETIME",
          "description": "Timestamp when the user profile was last updated."
        }
      ],
      "primary_key": [
        "user_id"
      ],
      "foreign_keys": []
    },
    {
      "table_name": "size_analytics",
      "table_description": "Table to store analytical data on size preferences and return rates.",
      "columns": [
        {
          "name": "analytics_id",
          "type": "INTEGER",
          "description": "Unique identifier for each analytics entry."
        },
        {
          "name": "region",
          "type": "VARCHAR",
          "description": "Region for which the analytics data is relevant."
        },
        {
          "name": "size_id",
          "type": "INTEGER",
          "description": "Foreign key referring to size_id in size_conversions table."
        },
        {
          "name": "demand_score",
          "type": "FLOAT",
          "description": "Score representing demand for the size in the region."
        },
        {
          "name": "return_rate",
          "type": "FLOAT",
          "description": "Rate of returns due to size misfit in the region."
        },
        {
          "name": "created_at",
          "type": "DATETIME",
          "description": "Timestamp when the analytics entry was created."
        },
        {
          "name": "updated_at",
          "type": "DATETIME",
          "description": "Timestamp when the analytics entry was last updated."
        }
      ],
      "primary_key": [
        "analytics_id"
      ],
      "foreign_keys": [
        {
          "column": "size_id",
          "references": {
            "table": "size_conversions",
            "column": "size_id"
          }
        }
      ]
    }
  ]
}
